6172	function _tickEmployeeSatisfaction(state, emp, company, netCash, timeMult) {
6173	  if (emp.burnoutLevel >= 3) return; // 重度倦怠员工不演化（已请假/离职中）
6174	
6175	  const day = state.player.day;
