6182	  const salaryRatio = emp.salary / roleBaseSalary;
6183	  const targetSalarySat = Math.min(80, 30 + salaryRatio * 25);
6184	  sat.salary = sat.salary + (targetSalarySat - sat.salary) * 0.02 * timeMult;
6185	
6186	  // === 工作强度满意度 ===
