6192	  } else {
6193	    emp.overtimeDays = Math.max(0, emp.overtimeDays - 0.1 * timeMult);
6194	    sat.workload = Math.min(90, sat.workload + 0.1 * timeMult);
6195	    emp.stressLevel = Math.max(20, emp.stressLevel - 0.2 * timeMult);
6196	  }
6197	
6198	  // === 成长空间满意度 ===
