6200	  const companyGrowth = (company.technologyScore + company.marketScore) / 200;
6201	  const targetGrowthSat = 30 + companyGrowth * 40;
6202	  sat.growth = sat.growth + (targetGrowthSat - sat.growth) * 0.01 * timeMult;
6203	
