6206	  const teamSizeFactor = Math.max(0, 1 - company.employees.length * 0.01);
6207	  const targetAtmosphere = 40 + teamSizeFactor * 40;
6208	  sat.atmosphere =
6209	    sat.atmosphere + (targetAtmosphere - sat.atmosphere) * 0.015 * timeMult;
6210	
6211	  // === 综合满意度 ===
6212	  emp.satisfaction = Math.round(
6213	    sat.salary * 0.35 +
6214	      sat.workload * 0.25 +
6215	      sat.growth * 0.25 +
6216	      sat.atmosphere * 0.15,
6217	  );
6218	
6219	  // === 倦怠风险计算 ===
6220	  // 连续加班、低满意度、高压力 → 倦怠风险增加
6221	  let burnoutFactor = 0;
6222	  burnoutFactor += emp.overtimeDays * 2; // 连续加班
6223	  burnoutFactor += (100 - emp.satisfaction) * 0.3; // 低满意度
6224	  burnoutFactor += emp.stressLevel * 0.4; // 高压力
6225	  burnoutFactor += (100 - sat.workload) * 0.3; // 工作强度不满
6226	
6227	  emp.burnoutRisk = Math.min(100, burnoutFactor);
6228	
6229	  // === 倦怠等级判定 ===
6230	  const oldBurnout = emp.burnoutLevel;
6231	  if (emp.burnoutRisk >= 80) {
6232	    emp.burnoutLevel = 3; // 重度倦怠
6233	  } else if (emp.burnoutRisk >= 60) {
6234	    emp.burnoutLevel = 2; // 中度倦怠
6235	  } else if (emp.burnoutRisk >= 40) {
6236	    emp.burnoutLevel = 1; // 轻度倦怠
6237	  } else {
6238	    emp.burnoutLevel = 0; // 正常
6239	  }
6240	
6241	  // === 健康值衰减 ===
6242	  if (emp.burnoutLevel >= 2) {
6243	    emp.health = Math.max(20, emp.health - 0.3 * timeMult);
6244	  } else if (emp.burnoutLevel === 1) {
6245	    emp.health = Math.max(30, emp.health - 0.1 * timeMult);
6246	  } else {
6247	    emp.health = Math.min(100, emp.health + 0.05 * timeMult);
6248	  }
6249	
6250	  // === 倦怠爆发判定 ===
6251	  if (emp.burnoutLevel >= 2 && !emp._burnoutTriggered) {
6252	    _triggerBurnout(state, emp, company);
