6539	    const weightedProgress = okr.keyResults.reduce(
6540	      (sum, kr) => sum + kr.progress * kr.weight,
6541	      0,
6542	    );
6543	    okr.progress = Math.round(weightedProgress / totalWeight);
6544	  }
6545	
6546	  // 进度里程碑通知
6547	  if (updated && okr.progress >= 25 && okr.progress < 50) {
6548	    StateManager.addMessage(
