7151	/** 每日技术债演化 */
7152	function _tickTechnicalDebt(state, product, timeMult) {
7153	  if (product.retired) return;
7154	
7155	  const debt = product.technicalDebt || 0;
7156	  const day = state.player.day;
7157	
7158	  // === 技术债自然积累 ===
7159	  // 基础积累：随着产品复杂度增加，技术债自然增长
7160	  const complexityFactor =
7161	    1 +
7162	    (product.features.length || 0) * 0.05 +
7163	    (product.versionIterationCount || 0) * 0.02;
7164	  const naturalAccumulation = 0.02 * complexityFactor * timeMult;
7165	
7166	  product.technicalDebt = Math.min(100, debt + naturalAccumulation);
7167	
7168	  // === Bug 率计算 ===
7169	  // bug 率与技术债正相关，评分负相关
7170	  const baseBugRate = 0.5; // 基础 bug 率（每千用户每日）
7171	  const debtBugMultiplier = 1 + debt / 20; // 技术债越高，bug 越多
7172	  const ratingFactor = 1 - (product.rating || 3.5) / 10; // 评分越低，bug 越多
7173	  product.bugRate =
7174	    baseBugRate *
7175	    debtBugMultiplier *
7176	    (0.5 + ratingFactor) *
7177	    (0.8 + Math.random() * 0.4);
7178	
7179	  // === 技术债危机判定 ===
7180	  if (debt >= 80 && !product.techDebtCrisis) {
7181	    _triggerTechDebtCrisis(state, product, "critical");
7182	  } else if (
7183	    debt >= 60 &&
7184	    !product.techDebtCrisis &&
7185	    Math.random() < 0.01 * timeMult
7186	  ) {
7187	    _triggerTechDebtCrisis(state, product, "moderate");
7188	  }
7189	
7190	  // === 重构加成衰减 ===
7191	  if (product.refactorBonus > 0) {
7192	    product.refactorBonus = Math.max(
7193	      0,
7194	      product.refactorBonus - 0.01 * timeMult,
7195	    );
7196	  }
7197	
7198	  // === 记录历史（每周）===
7199	  if (day % 7 === 0 || timeMult >= 90) {
7200	    product.techDebtHistory.push({
7201	      day: day,
7202	      debt: product.technicalDebt,
7203	      bugRate: product.bugRate,
7204	      sources: { ...product.techDebtSources },
7205	    });
7206	    product.bugHistory.push({
7207	      day: day,
7208	      bugRate: product.bugRate,
7209	      usersAffected: Math.round((product.users * product.bugRate) / 1000),
7210	    });
7211	    if (product.techDebtHistory.length > 52) product.techDebtHistory.shift();
7212	    if (product.bugHistory.length > 52) product.bugHistory.shift();
7213	  }
7214	}
