7393	// ====== P0-2: AARRR 用户增长漏斗演化 ======
7394	/** 每日 AARRR 漏斗演化 */
7395	function _tickAARRRFunnel(state, product, timeMult) {
7396	  const users = product.users || 0;
7397	  if (users <= 0) return;
7398	
7399	  // === A: Acquisition (获客) ===
7400	  // 自然增长 + 广告获客 + 病毒传播
7401	  const organicGrowth = Math.round(users * 0.001 * timeMult); // 自然增长 0.1%/天
7402	  const adGrowth = _calculateAdGrowth(state, product, timeMult);
7403	  const viralGrowth = _calculateViralGrowth(product, timeMult);
7404	
7405	  product.newUsersToday = organicGrowth + adGrowth + viralGrowth;
7406	
7407	  // 计算获客成本
7408	  if (product.adSpend > 0) {
7409	    product.cac = adGrowth > 0 ? product.adSpend / adGrowth : 0;
7410	  } else {
7411	    product.cac = 0;
7412	  }
7413	
7414	  // === A: Activation (激活) ===
7415	  // 激活率受产品评分、新手引导影响
7416	  const newActivated = Math.round(
7417	    product.newUsersToday * product.activationRate,
7418	  );
7419	  product.activatedUsers = newActivated;
7420	
7421	  // 新手引导完成率影响激活率
7422	  if (product.onboardingCompleteRate < 0.8 && Math.random() < 0.05) {
7423	    product.onboardingCompleteRate = Math.min(
7424	      0.95,
7425	      product.onboardingCompleteRate + 0.02,
7426	    );
7427	    product.activationRate = Math.min(0.6, product.activationRate + 0.01);
7428	  }
7429	
7430	  // === R: Retention (留存) ===
7431	  // 日活/周活/月活计算
7432	  product.dau = Math.round(users * (0.3 + (product.rating / 5) * 0.3)); // 30%-60% 日活
7433	  product.wau = Math.round(users * (0.5 + (product.rating / 5) * 0.3)); // 50%-80% 周活
7434	  product.mau = Math.round(users * (0.7 + (product.rating / 5) * 0.25)); // 70%-90% 月活
7435	
7436	  // 留存率演化：评分高→留存提升，评分低→留存下降
7437	  const ratingFactor = product.rating / 5;
7438	  const retentionChange = (ratingFactor - 0.5) * 0.002 * timeMult;
7439	
7440	  product.retentionD1 = Math.max(
7441	    0.1,
7442	    Math.min(0.8, product.retentionD1 + retentionChange),
7443	  );
7444	  product.retentionD7 = Math.max(
7445	    0.05,
7446	    Math.min(0.6, product.retentionD7 + retentionChange * 0.7),
7447	  );
7448	  product.retentionD30 = Math.max(
7449	    0.02,
7450	    Math.min(0.4, product.retentionD30 + retentionChange * 0.4),
7451	  );
7452	
7453	  // 记录留存历史
7454	  if (state.player.day % 7 === 0 || timeMult >= 90) {
7455	    product.retentionHistory.push({
7456	      day: state.player.day,
7457	      d1: product.retentionD1,
7458	      d7: product.retentionD7,
7459	      d30: product.retentionD30,
7460	      dau: product.dau,
7461	      mau: product.mau,
7462	    });
7463	    // 限制历史记录长度
7464	    if (product.retentionHistory.length > 52) {
7465	      product.retentionHistory.shift();
7466	    }
7467	  }
7468	
7469	  // === R: Revenue (变现) ===
7470	  // 付费率演化
7471	  const payRateChange = (product.rating - 3.5) * 0.001 * timeMult;
7472	  product.payRate = Math.max(
7473	    0.01,
7474	    Math.min(0.3, product.payRate + payRateChange),
7475	  );
7476	
7477	  product.payingUsers = Math.round(users * product.payRate);
7478	
7479	  // ARPU 计算（基于产品类别）
7480	  const categoryInfo = PRODUCT_CATEGORIES[product.category];
7481	  const baseArpu = categoryInfo?.baseArpu || 0.5; // 元/天/用户
7482	  const arpuMultiplier =
7483	    (product.rating / 3.5) * (1 + product.features.length * 0.05);
7484	  product.arpu = baseArpu * arpuMultiplier;
7485	
7486	  // ARPPU（每付费用户平均收入）
7487	  if (product.payingUsers > 0) {
7488	    product.arppu = (product.arpu * users) / product.payingUsers;
7489	  }
7490	
7491	  // LTV 计算：ARPU × 平均留存天数
7492	  const avgLifetime = 1 / (1 - product.retentionD30); // 简化模型
7493	  product.ltv = product.arpu * avgLifetime * 30; // 月度 LTV
7494	
7495	  // === R: Referral (推荐) ===
7496	  // 病毒系数 K = 分享率 × 推荐转化率 × 分享次数
7497	  const shareRate =
7498	    product.rating >= 4 ? 0.05 : product.rating >= 3.5 ? 0.02 : 0.01;
7499	  product.referralRate = shareRate;
7500	  product.kFactor = shareRate * product.referralConversion * 3; // 每个用户平均分享3次
7501	
7502	  // 病毒传播
7503	  const viralNewUsers = Math.round(
7504	    ((users * product.kFactor) / product.viralCycleTime) * timeMult,
7505	  );
7506	  product.viralNewUsers = viralNewUsers;
7507	
7508	  // === 漏斗数据记录 ===
7509	  product.funnelData.impressions += product.newUsersToday * 10 * timeMult; // 曝光量 ≈ 新增×10
7510	  product.funnelData.clicks += Math.round(product.funnelData.impressions * 0.1);
7511	  product.funnelData.registrations += product.newUsersToday;
7512	  product.funnelData.activated += newActivated;
7513	  product.funnelData.retainedD7 += Math.round(users * product.retentionD7);
7514	  product.funnelData.retainedD30 += Math.round(users * product.retentionD30);
7515	  product.funnelData.paying += product.payingUsers;
7516	  product.funnelData.referred += viralNewUsers;
7517	
7518	  // 记录漏斗历史（每周）
7519	  if (state.player.day % 7 === 0 || timeMult >= 90) {
7520	    product.funnelHistory.push({
7521	      day: state.player.day,
7522	      funnel: { ...product.funnelData },
7523	      cac: product.cac,
7524	      ltv: product.ltv,
7525	      kFactor: product.kFactor,
7526	    });
7527	    if (product.funnelHistory.length > 52) {
7528	      product.funnelHistory.shift();
7529	    }
7530	  }
7531	
7532	  // === LTV/CAC 比率检查 ===
7533	  if (product.cac > 0 && product.ltv > 0) {
7534	    const ltvcacRatio = product.ltv / product.cac;
7535	    if (ltvcacRatio < 1 && timeMult >= 90) {
7536	      StateManager.addMessage(
7537	        `⚠️ 「${product.name}」LTV/CAC < 1（${ltvcacRatio.toFixed(1)}），获客成本超过用户价值！`,
7538	        "warning",
7539	      );
7540	    } else if (ltvcacRatio > 3 && timeMult >= 90) {
7541	      StateManager.addMessage(
7542	        `📈 「${product.name}」LTV/CAC = ${ltvcacRatio.toFixed(1)}，获客效率优秀！`,
7543	        "success",
7544	      );
7545	    }
7546	  }
7547	
7548	  // === 病毒爆发通知 ===
7549	  if (product.kFactor > 1 && viralNewUsers > product.newUsersToday * 0.3) {
7550	    StateManager.addMessage(
7551	      `🚀 「${product.name}」病毒传播爆发！K因子=${product.kFactor.toFixed(2)}，今日推荐带来+${viralNewUsers}用户`,
7552	      "success",
7553	    );
7554	  }
7555	}
