7557	/** 计算广告获客 */
7558	function _calculateAdGrowth(state, product, timeMult) {
7559	  if (product.adSpend <= 0) return 0;
7560	
7561	  // 广告效果：基于投入金额 + 产品竞争力
7562	  const baseEfficiency = 50; // 每元广告费带来多少曝光
7563	  const efficiencyMult = 0.8 + (product.competitiveness / 100) * 0.4;
7564	  const clickRate = 0.05; // 5% 点击率
7565	  const installRate = 0.2; // 20% 安装率
7566	
7567	  const impressions = product.adSpend * baseEfficiency * efficiencyMult;
7568	  const clicks = Math.round(impressions * clickRate);
7569	  const installs = Math.round(clicks * installRate);
7570	
7571	  return Math.max(0, (installs * timeMult) / 90); // 按天分摊
7572	}
7573	
7574	/** 计算病毒传播 */
7575	function _calculateViralGrowth(product, timeMult) {
7576	  if (product.kFactor <= 0) return 0;
7577	  const users = product.users || 0;
7578	  return Math.round(
7579	    ((users * product.kFactor) / product.viralCycleTime) * timeMult,
7580	  );
7581	}
