8220	function acceptAcquisition(state, offer) {
8221	  const startup = state.startup;
8222	  const company = startup.company;
8223	  if (!company || !offer) return { success: false };
8224	
8225	  // 执行收购
8226	  startup.flags.exited = true;
8227	  startup.flags.exitType = "acquired";
8228	  startup.flags.exitDay = state.player.day;
8229	  startup.flags.exitValue = offer.playerShareValue;
8230	
8231	  startup.history.exitedDay = state.player.day;
8232	  startup.history.exitType = "acquired";
8233	  startup.history.exitValue = offer.playerShareValue;
8234	
8235	  // 玩家获得现金
8236	  state.resources.cash += offer.playerShareValue;
8237	
8238	  // 在企业命运系统中标记
8239	  if (state.enterpriseFate && state.enterpriseFate.companies) {
8240	    const fateCo = state.enterpriseFate.companies[company.id];
8241	    if (fateCo) {
8242	      fateCo.ceasedExistence = true;
8243	      fateCo.ceasedAt = state.player.day;
8244	      fateCo.absorbedBy = offer.acquirerCid;
8245	      fateCo.absorbedName = offer.acquirerName + "旗下";
8246	    }
8247	
8248	    // 收购方增强
8249	    const acquirerCo = state.enterpriseFate.companies[offer.acquirerCid];
8250	    if (acquirerCo) {
8251	      acquirerCo.marketShare = Math.min(40, acquirerCo.marketShare + 2);
8252	      acquirerCo.health = Math.min(100, acquirerCo.health + 5);
8253	    }
8254	  }
8255	
8256	  StateManager.addMessage(
8257	    "🤝 「" +
8258	      company.name +
8259	      "」被「" +
8260	      offer.acquirerName +
8261	      "」收购！你获得¥" +
