8271	function bankrupt(state) {
8272	  const startup = state.startup;
8273	  const company = startup.company;
8274	  if (!company) return;
8275	
8276	  startup.flags.exited = true;
8277	  startup.flags.exitType = "bankrupt";
8278	  startup.flags.exitDay = state.player.day;
8279	  startup.flags.exitValue = 0;
8280	
8281	  startup.history.exitedDay = state.player.day;
8282	  startup.history.exitType = "bankrupt";
8283	  startup.history.exitValue = 0;
8284	
8285	  // 资产清算
8286	  const assetRecovery = Math.round(company.cashReserve * 0.3); // 只能收回30%
8287	  company.cashReserve = assetRecovery;
8288	
8289	  // 玩家获得剩余现金（如果有）
8290	  state.resources.cash += assetRecovery;
8291	
8292	  // 声誉损失
8293	  state.status.health = Math.max(0, state.status.health - 10);
8294	  state.player.fame = Math.max(0, state.player.fame - 10);
8295	
8296	  // 在企业命运系统中标记
8297	  if (state.enterpriseFate && state.enterpriseFate.companies && company.id) {
8298	    const fateCo = state.enterpriseFate.companies[company.id];
8299	    if (fateCo) {
8300	      fateCo.ceasedExistence = true;
8301	      fateCo.ceasedAt = state.player.day;
8302	      fateCo.health = 0;
